        private static final String TRANSLATIONS_MENU = "translations_menu.json";
        private static final String TRANSLATIONS_OVERHEAD = "translations_overhead.json";
        private static final String TRANSLATIONS_GAME_MESSAGE = "translations_game_message.json";
        private static final String TRANSLATIONS_WELCOME = "translations_welcome.json";
        private static final String TRANSLATIONS_SETTINGS = "translations_settings.json";

        private volatile Filepath remoteCacheDirectory;
        private volatile Filepath localTranslationDirectory;

        private boolean configureRemoteCacheDirectory(Filepath directory) {
            Filepath previous = remoteCacheDirectory;
            remoteCacheDirectory = directory;
            return previous == null ? directory != null : !previous.equals(directory);
        }

        private void configureLocalDirectory(Filepath directory) {
            localTranslationDirectory = directory;
        }

        private String localFingerprint() {
            Filepath directory = localTranslationDirectory;
            StringBuilder fingerprint = new StringBuilder();
            for (String fileName : RemoteTranslationService.REQUIRED_FILES) {
                Filepath file = directory == null ? null : directory.joinSegment(fileName);
                if (file == null || !file.isFile()) {
                    fingerprint.append(fileName).append(":missing;");
                    continue;
                }
                try {
                    fingerprint.append(fileName)
                        .append(':').append(file.size())
                        .append(':').append(file.getLastModifiedTime().toMillis())
                        .append(';');
                } catch (IOException e) {
                    fingerprint.append(fileName).append(":error;");
                }
            }
            return fingerprint.toString();
        }

        private boolean areLocalFilesValid() {
            Filepath directory = localTranslationDirectory;
            if (directory == null) {
                return true;
            }

            for (String fileName : RemoteTranslationService.REQUIRED_FILES) {
                Filepath file = directory.joinSegment(fileName);
                if (!file.isFile()) {
                    continue;
                }

                try (InputStream input = file.openInputStream()) {
                    TranslationLookupHelper.parseJsonMapStrict(input);
                } catch (Exception e) {
                    log.warn("Aguardando a conclusao da edicao do arquivo local: {}", file);
                    return false;
                }
            }
            return true;
        }

        private TranslationState loadState(TraduccionEspanolConfig.TranslationSource source) {
            Map<String, String> translations = loadMap(TRANSLATIONS, source);
            Map<String, String> translationsSkills = loadMap(TRANSLATIONS_SKILLS, source);
            Map<String, String> translationsQuests = loadMap(TRANSLATIONS_QUESTS, source);
            Map<String, String> translationsItems = loadMap(TRANSLATIONS_ITEMS, source);
            Map<String, String> translationsMenu = loadMap(TRANSLATIONS_MENU, source);
            Map<String, String> translationsOverhead = loadMap(TRANSLATIONS_OVERHEAD, source);
            Map<String, String> translationsGameMessage = loadMap(TRANSLATIONS_GAME_MESSAGE, source);
            Map<String, String> translationsWelcome = loadMap(TRANSLATIONS_WELCOME, source);
            Map<String, String> translationsSettings = loadMap(TRANSLATIONS_SETTINGS, source);

            TranslationState state = new TranslationState(
                translations,
                translationsSkills,
                translationsQuests,
                translationsItems,
                translationsMenu,
                translationsOverhead,
                translationsGameMessage,
                translationsWelcome,
                translationsSettings,
                new HashSet<>(translations.values()),
                new HashSet<>(translationsSkills.values()),
                new HashSet<>(translationsQuests.values()),
                new HashSet<>(translationsItems.values()),
                new HashSet<>(translationsMenu.values()),
                new HashSet<>(translationsGameMessage.values()),
                new HashSet<>(translationsWelcome.values()),
                new HashSet<>(translationsSettings.values()),
                TranslationLookupHelper.compileRegexTranslations(translations),
                TranslationLookupHelper.compileRegexTranslations(translationsOverhead),
                TranslationLookupHelper.compileRegexTranslations(translationsGameMessage),
                TranslationLookupHelper.compileRegexTranslations(translationsWelcome),
                buildReverseMenuMap(translationsMenu)
            );

            log.info(
                "Diccionarios cargados: dialogos={} skills={} quests={} items={} menu={} "
                    + "overhead={} gameMessages={} welcome={} settings={} regex={} overheadRegex={} welcomeRegex={}",
                translations.size(),
                translationsSkills.size(),
                translationsQuests.size(),
                translationsItems.size(),
                translationsMenu.size(),
                translationsOverhead.size(),
                translationsGameMessage.size(),
                translationsWelcome.size(),
                translationsSettings.size(),
                state.regexTranslations.size(),
                state.regexOverheadTranslations.size(),
                state.regexWelcomeTranslations.size()
            );
            return state;
        }

        private Map<String, String> loadMap(
            String fileName,
            TraduccionEspanolConfig.TranslationSource source
        ) {
            if (source == TraduccionEspanolConfig.TranslationSource.LOCAL) {
                return loadLocalMap(fileName);
            }

            Filepath cacheDirectory = remoteCacheDirectory;
            if (cacheDirectory == null) {
                return Collections.emptyMap();
            }

            Filepath remoteFile = cacheDirectory.joinSegment(fileName);
            if (!remoteFile.isFile()) {
                log.warn("Arquivo ausente no cache remoto: {}", fileName);
                return Collections.emptyMap();
            }

            try (InputStream input = remoteFile.openInputStream()) {
                return TranslationLookupHelper.parseJsonMap(input);
            } catch (Exception e) {
                log.warn("Cache remoto invalido para {}", fileName, e);
                return Collections.emptyMap();
            }
        }

        private Map<String, String> loadLocalMap(String fileName) {
            Filepath directory = localTranslationDirectory;
            if (directory == null || !directory.isDirectory()) {
                return Collections.emptyMap();
            }

            Filepath localFile = directory.joinSegment(fileName);
            if (!localFile.isFile()) {
                log.warn("Arquivo local de traducoes ausente: {}", localFile);
                return Collections.emptyMap();
            }

            try (InputStream input = localFile.openInputStream()) {
                return TranslationLookupHelper.parseJsonMapStrict(input);
            } catch (Exception e) {
                log.warn("Arquivo local de traducoes invalido: {}", localFile, e);
                return Collections.emptyMap();
            }
        }

        private Map<String, String> buildReverseMenuMap(Map<String, String> source) {
            Map<String, String> reverse = new LinkedHashMap<>();
            for (Map.Entry<String, String> entry : source.entrySet()) {
                String key = stripMenuText(entry.getKey());
                String value = normalizeMenuLookup(entry.getValue());
                if (key.isEmpty() || value.isEmpty()) {
                    continue;
                }
                reverse.putIfAbsent(value, key);
            }
            return reverse;
        }

        private String stripMenuText(String text) {
            return text.replaceAll("<[^>]+>", "").trim();
        }

        private String normalizeMenuLookup(String text) {
            return stripMenuText(text).toLowerCase(Locale.ROOT);
        }
    }

    @Provides
    TraduccionEspanolConfig provideConfig(ConfigManager configManager) {
        return configManager.getConfig(TraduccionEspanolConfig.class);
    }

    /**
     * Faz quebra de linha justificada: distribui palavras pra cada linha ter tamanho similar.
     * @param text texto a quebrar
     * @param maxCharsPorLinha número máximo de caracteres por linha
     * @return texto com quebras de linha (\n) balanceadas
     */
    }

package com.osrstraduccion;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;

import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

final class TranslationLookupHelper
{
    private static final Pattern BR_TAG = Pattern.compile("(?i)<br\\s*/?>");
    private static final Pattern HTML_TAG = Pattern.compile("<[^>]+>");
    private static final Pattern PLACEHOLDER = Pattern.compile("\\[[^\\]]+\\]");

    private TranslationLookupHelper()
    {
    }

    static Map<String, String> loadMap(Class<?> owner, String path)
    {
        try (InputStream is = owner.getResourceAsStream(path))
        {
            if (is == null)
            {
                return Collections.emptyMap();
            }
            return parseJsonMap(is);
        }
        catch (Exception e)
        {
            return Collections.emptyMap();
        }
    }

    static Map<String, String> parseJsonMap(InputStream is)
    {
        try
        {
            return parseJsonMapStrict(is);
        }
        catch (Exception e)
        {
            return Collections.emptyMap();
        }
    }

    static Map<String, String> parseJsonMapStrict(InputStream is) throws IOException
    {
        try
        {
            JsonElement element = new JsonParser().parse(
                new InputStreamReader(is, StandardCharsets.UTF_8)
            );
            if (element == null || !element.isJsonObject())
            {
                throw new IOException("A raiz do JSON deve ser um objeto");
            }

            JsonObject object = element.getAsJsonObject();
            Map<String, String> result = new LinkedHashMap<>();
            for (Map.Entry<String, JsonElement> entry : object.entrySet())
            {
                JsonElement value = entry.getValue();
                if (value == null || !value.isJsonPrimitive()
                    || !value.getAsJsonPrimitive().isString())
                {
                    throw new IOException("Traducao invalida para a chave: " + entry.getKey());
                }
                result.putIfAbsent(entry.getKey(), value.getAsString());
            }
            return result;
        }
        catch (IOException e)
        {
            throw e;
        }
        catch (Exception e)
        {
            throw new IOException("JSON de traducoes invalido", e);
        }
    }

    static List<PatternEntry> compileRegexTranslations(Map<String, String> source)
    {
        PatternList entries = new PatternList();
        for (Map.Entry<String, String> entry : source.entrySet())
        {
            String key = entry.getKey();
            String translation = entry.getValue();
            if (key == null || translation == null || !PLACEHOLDER.matcher(key).find())
            {
                continue;
            }

            if (isIdentityTemplate(key, translation))
            {
                continue;
            }

            int specificity = staticTextLength(key);
            if (specificity == 0)
            {
                // A key made only of brackets is an alternative/choice form,
                // not a safe generic pattern.  It would match every text,
                // including NPC names such as "Banker".
                continue;
            }

            String[] parts = PLACEHOLDER.split(key, -1);
            Matcher names = PLACEHOLDER.matcher(key);
            boolean onlyPunctuation = !LETTER.matcher(PLACEHOLDER.matcher(key).replaceAll("")).find();
            StringBuilder pattern = new StringBuilder();
            for (int i = 0; i < parts.length; i++)
            {
                pattern.append(Pattern.quote(parts[i]));
                if (i < parts.length - 1 && names.find())
                {
                    pattern.append(placeholderRegex(names.group(), onlyPunctuation));
                }
            }
            entries.add(new PatternEntry(
                Pattern.compile(pattern.toString()),
                translation,
                specificity,
                parts[0],
                parts[parts.length - 1]
            ));
        }
        entries.sort((left, right) -> Integer.compare(right.specificity, left.specificity));
        return entries;
    }

    private static final Pattern LETTER = Pattern.compile("\\p{L}");

    /**
     * Un nombre ([player], [lad/lass], [rank]...) es corto y sin signos de frase: si el comodín pudiera
     * tragarse cualquier texto, "[player]?" o "You [player]?" convertirían una pregunta inglesa entera en
     * "¿...?" o "¿Tú ...?" y la darían por traducida. Lo mismo con las claves que solo tienen signos.
     */
    static String placeholderRegex(String placeholder, boolean onlyPunctuation)
    {
        String name = placeholder.toLowerCase(java.util.Locale.ROOT);
        if (name.contains("player"))
        {
            return "([^.!?,;:]{1,12}?)"; // los nombres de jugador tienen como mucho 12 caracteres
        }
        if (name.contains("/") || name.contains("rank") || name.contains("name"))
        {
            return "([^.!?,;:]{1,30}?)";
        }
        if (onlyPunctuation)
        {
            return "([^.!?]{1,30}?)";
        }
        return "(.+?)";
    }

    private static boolean isIdentityTemplate(String key, String translation)
    {
        return templateSignature(key).equals(templateSignature(translation));
    }

    private static String templateSignature(String text)
    {
        return PLACEHOLDER.matcher(text).replaceAll(Matcher.quoteReplacement("\u0000"));
    }

    private static int staticTextLength(String text)
    {
        Matcher matcher = PLACEHOLDER.matcher(text);
        int length = 0;
        int end = 0;
        while (matcher.find())
        {
            length += matcher.start() - end;
            end = matcher.end();
        }
        return length + text.length() - end;
    }

    static String findTranslation(Map<String, String> source, String lookup)
    {
        return source.get(lookup);
    }

    static String findTranslation(Map<String, String> source, List<PatternEntry> patterns, String lookup)
    {
        String translation = findTranslation(source, lookup);
        if (translation != null || patterns == null || patterns.isEmpty())
        {
            return translation;
        }
        return findRegexTranslation(patterns, lookup);
    }

    static String findRegexTranslation(List<PatternEntry> patterns, String lookup)
    {
        if (patterns instanceof PatternList)
        {
            // Las ventanas se repasan en cada fotograma: se recuerda el resultado (también si no hay traducción)
            PatternList list = (PatternList) patterns;
            String cached = list.cache.get(lookup);
            if (cached != null)
            {
                return cached == NO_MATCH ? null : cached;
            }
            String result = searchRegexTranslation(patterns, lookup);
            if (list.cache.size() >= PatternList.MAX_CACHE)
            {
                list.cache.clear();
            }
            list.cache.put(lookup, result == null ? NO_MATCH : result);
            return result;
        }
        return searchRegexTranslation(patterns, lookup);
    }

    /** Marca "sin traducción" en la memoria (se compara por identidad). */
    @SuppressWarnings("StringOperationCanBeSimplified")
    private static final String NO_MATCH = new String("");

    private static String searchRegexTranslation(List<PatternEntry> patterns, String lookup)
    {
        for (PatternEntry entry : patterns)
        {
            // Filtro rápido: el texto debe empezar y terminar como el patrón (evita casi todas las regex)
            if (!lookup.startsWith(entry.prefix) || !lookup.endsWith(entry.suffix)
                || lookup.length() < entry.prefix.length() + entry.suffix.length())
            {
                continue;
            }
            Matcher matcher = entry.pattern.matcher(lookup);
            if (!matcher.matches())
            {
                continue;
            }

            String result = entry.translation;
            boolean replacedPlaceholder = false;
            for (int i = 1; i <= matcher.groupCount(); i++)
            {
                Matcher placeholderMatcher = PLACEHOLDER.matcher(result);
                if (!placeholderMatcher.find())
                {
                    break;
                }

                result = result.substring(0, placeholderMatcher.start())
                    + matcher.group(i)
                    + result.substring(placeholderMatcher.end());
                replacedPlaceholder = true;
            }
            if (replacedPlaceholder && !lookup.equals(result))
            {
                return result;
            }
        }
        return null;
    }

    private static final Pattern CHAT_COLOR_CODE = Pattern.compile("@[a-z][a-z0-9_]*@");
    private static final Pattern LEADING_CHAT_COLOR_CODES = Pattern.compile("^(?:@[a-z][a-z0-9_]*@)+");

    // Colores del juego (<col=ff0000>) y de RuneLite (<colHIGHLIGHT>, <colNORMAL>), usados por otros plugins
    private static final String COLOR_TAG = "<col(?:=[0-9a-fA-F]{6}|[A-Z]+)>";
    private static final Pattern WHOLE_COLORED = Pattern.compile("^\\s*(" + COLOR_TAG + ")([^<]*)(</col>)?\\s*$");
    private static final Pattern COLORED_SEGMENT = Pattern.compile(
        "(" + COLOR_TAG + ")(.*?)(</col>|(?=<col)|$)", Pattern.DOTALL);

    /**
     * Recoloca en la traducción las partes coloreadas del mensaje original.
     * Ej.: original "GE average <col=00ff00>1,793</col>" y traducción "promedio GE 1,793"
     * -> "promedio GE <col=00ff00>1,793</col>". Solo recolorea textos que aparecen igual en la traducción
     * (números, nombres, objetos que se dejan en inglés); el resto queda con el color normal.
     */
    static String reapplyColors(String original, String translation)
    {
        if (original == null || translation == null || !original.contains("<col"))
        {
            return translation;
        }
        if (translation.contains("<col"))
        {
            return translation; // la traducción ya trae sus propios colores
        }
        // Mensaje entero de un solo color (p. ej. avisos en rojo): la traducción entera con ese color
        Matcher whole = WHOLE_COLORED.matcher(original);
        if (whole.matches())
        {
            return whole.group(1) + translation + "</col>";
        }
        StringBuilder result = new StringBuilder();
        int cursor = 0;
        Matcher matcher = COLORED_SEGMENT.matcher(original);
        while (matcher.find())
        {
            String text = HTML_TAG.matcher(matcher.group(2)).replaceAll("").trim();
            if (text.isEmpty())
            {
                continue;
            }
            int at = translation.indexOf(text, cursor);
            if (at < 0)
            {
                continue;
            }
            result.append(translation, cursor, at)
                .append(matcher.group(1)).append(text).append("</col>");
            cursor = at + text.length();
        }
        if (cursor == 0)
        {
            return translation;
        }
        return result.append(translation.substring(cursor)).toString();
    }

    /** Remove códigos de cor do chat do jogo, como "@mes_hl_cya@" ou "@red@". */
    static String stripChatColorCodes(String text)
    {
        return text == null ? "" : CHAT_COLOR_CODE.matcher(text).replaceAll("");
    }

    /** Códigos de cor no início da mensagem (para recolocá-los na tradução). */
    static String leadingChatColorCodes(String text)
    {
        if (text == null)
        {
            return "";
        }
        Matcher matcher = LEADING_CHAT_COLOR_CODES.matcher(text);
        return matcher.find() ? matcher.group() : "";
    }

    static String cleanText(String text)
    {
        if (text == null)
        {
            return "";
        }

        if (text.indexOf('<') < 0 && !hasDoubleSpace(text))
        {
            return text.trim(); // caso más común: texto sin etiquetas
        }
        String clean = BR_TAG.matcher(text).replaceAll(" ");
        clean = HTML_TAG.matcher(clean).replaceAll(" ");
        return WHITESPACE.matcher(clean).replaceAll(" ").trim();
    }

    private static boolean hasDoubleSpace(String text)
    {
        for (int i = 0; i < text.length(); i++)
        {
            char c = text.charAt(i);
            if (Character.isWhitespace(c) && (c != ' ' || (i + 1 < text.length()
                && Character.isWhitespace(text.charAt(i + 1)))))
            {
                return true;
            }
        }
        return false;
    }

    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
    private static final Pattern SPACE_BEFORE_PUNCTUATION = Pattern.compile("\\s+([.,!?])");
    private static final Pattern HARDCORE_IRONMEN = Pattern.compile("([Hh])ardcore Ironmen ");

    static String normalizeLookupText(String text)
    {
        String result = SPACE_BEFORE_PUNCTUATION.matcher(text).replaceAll("$1");
        if (result.contains("Ironmen "))
        {
            result = HARDCORE_IRONMEN.matcher(result).replaceAll("$1ardcore Ironman ")
                .replace("standard Ironmen ", "standard Ironman ");
        }
        return result;
    }

    static final class PatternEntry
    {
        private final Pattern pattern;
        private final String translation;
        private final int specificity;
        private final String prefix;
        private final String suffix;

        private PatternEntry(Pattern pattern, String translation, int specificity, String prefix, String suffix)
        {
            this.pattern = pattern;
            this.translation = translation;
            this.specificity = specificity;
            this.prefix = prefix;
            this.suffix = suffix;
        }
    }

    /** Lista de patrones con memoria de resultados. Al recargar los diccionarios se crea una nueva. */
    static final class PatternList extends ArrayList<PatternEntry>
    {
        private static final long serialVersionUID = 1L;
        private static final int MAX_CACHE = 20000;
        private final transient Map<String, String> cache = new ConcurrentHashMap<>();

        @Override
        public boolean equals(Object o)
        {
            return this == o;
        }

        @Override
        public int hashCode()
        {
            return System.identityHashCode(this);
        }
    }
}

package com.osrstraduccion;

import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

final class WelcomeTranslationService {
    private static final int WELCOME_SCREEN = 378;
    private static final String LAST_LOGIN_TEMPLATE = "You last logged in [value] ago.";
    private static final String HANS_TEMPLATE_KEY = "__hans.template";
    private static final Pattern WELCOME_LAST_LOGIN_PATTERN =
        Pattern.compile("^You last logged in (.+) ago\\.$");
    private static final Pattern ENGLISH_DURATION_UNIT_PATTERN =
        Pattern.compile("\\b(\\d[\\d,]*)\\s+(day|days|hour|hours|minute|minutes|second|seconds)\\b");
    private static final Pattern ENGLISH_SINGLE_DURATION_UNIT_PATTERN =
        Pattern.compile("\\b(a|an)\\s+(day|hour|minute|second)\\b");
    private static final Pattern HANS_PATTERN = Pattern.compile(
        "^You've spent (\\d[\\d,]*) (day|days), (\\d[\\d,]*) (hour|hours), "
            + "(\\d[\\d,]*) (minute|minutes) in the world since you arrived "
            + "(\\d[\\d,]*) (day|days) ago\\.$"
    );
    private static final Pattern NUMBER_PATTERN = Pattern.compile("(\\d[\\d,]*)");

    String translateSpecialText(
        String lookup,
        int interfaceId,
        Set<Integer> loginInterfaceGroups,
        Map<String, String> translations
    ) {
        if (isHansTimePlayedMessage(lookup)) {
            return translateHans(lookup, translations);
        }

        if (interfaceId != WELCOME_SCREEN && !loginInterfaceGroups.contains(interfaceId)) {
            return null;
        }

        Matcher matcher = WELCOME_LAST_LOGIN_PATTERN.matcher(lookup);
        if (!matcher.matches()) {
            return null;
        }

        String template = translations.get(LAST_LOGIN_TEMPLATE);
        if (template == null || template.isEmpty()) {
            return null;
        }

        return template.replace("[value]", translateEnglishDuration(matcher.group(1), translations));
    }

    private boolean isHansTimePlayedMessage(String lookup) {
        return lookup.startsWith("You've spent")
            && lookup.contains("in the world since you arrived")
            && lookup.endsWith("ago.");
    }

    private String translateHans(String clean, Map<String, String> translations) {
        String template = translations.get(HANS_TEMPLATE_KEY);
        if (template == null || template.isEmpty()) {
            return null;
        }

        Matcher matcher = HANS_PATTERN.matcher(clean);
        String daysInWorld;
        String daysInWorldUnit;
        String hoursInWorld;
        String hoursInWorldUnit;
        String minutesInWorld;
        String minutesInWorldUnit;
        String daysSinceArrival;
        String daysSinceArrivalUnit;
        if (matcher.matches()) {
            daysInWorld = matcher.group(1);
            daysInWorldUnit = translateDurationUnit(matcher.group(2), translations);
            hoursInWorld = matcher.group(3);
            hoursInWorldUnit = translateDurationUnit(matcher.group(4), translations);
            minutesInWorld = matcher.group(5);
            minutesInWorldUnit = translateDurationUnit(matcher.group(6), translations);
            daysSinceArrival = matcher.group(7);
            daysSinceArrivalUnit = translateDurationUnit(matcher.group(8), translations);
        } else {
            Matcher fallback = NUMBER_PATTERN.matcher(clean);
            daysInWorld = findNext(fallback);
            hoursInWorld = findNext(fallback);
            minutesInWorld = findNext(fallback);
            daysSinceArrival = findNext(fallback);
            daysInWorldUnit = translateDurationUnit("days", translations);
            hoursInWorldUnit = translateDurationUnit("hours", translations);
            minutesInWorldUnit = translateDurationUnit("minutes", translations);
            daysSinceArrivalUnit = translateDurationUnit("days", translations);
        }

        return template
            .replace("[daysInWorld]", daysInWorld)
            .replace("[daysUnit]", daysInWorldUnit)
            .replace("[hoursInWorld]", hoursInWorld)
            .replace("[hoursUnit]", hoursInWorldUnit)
            .replace("[minutesInWorld]", minutesInWorld)
            .replace("[minutesUnit]", minutesInWorldUnit)
            .replace("[daysSinceArrival]", daysSinceArrival)
            .replace("[daysSinceArrivalUnit]", daysSinceArrivalUnit);
    }

    private String findNext(Matcher matcher) {
        return matcher.find() ? matcher.group(1) : "";
    }

    private String translateEnglishDuration(String text, Map<String, String> translations) {
        Matcher matcher = ENGLISH_DURATION_UNIT_PATTERN.matcher(text);
        StringBuffer translated = new StringBuffer();
        boolean found = false;

        while (matcher.find()) {
            found = true;
            String amount = matcher.group(1);
            String unit = matcher.group(2);
            matcher.appendReplacement(
                translated,
                Matcher.quoteReplacement(amount + " " + translateDurationUnit(unit, translations))
            );
        }

        if (!found) {
            Matcher singleMatcher = ENGLISH_SINGLE_DURATION_UNIT_PATTERN.matcher(text);
            StringBuffer singleTranslated = new StringBuffer();
            boolean singleFound = false;

            while (singleMatcher.find()) {
                singleFound = true;
                String unit = singleMatcher.group(2);
                singleMatcher.appendReplacement(
                    singleTranslated,
                    Matcher.quoteReplacement("1 " + translateDurationUnit(unit, translations))
                );
            }

            if (!singleFound) {
                return text;
            }

            singleMatcher.appendTail(singleTranslated);
            return singleTranslated.toString();
        }

        matcher.appendTail(translated);
        return translated.toString();
    }

    private String translateDurationUnit(String unit, Map<String, String> translations) {
        String translated = translations.get("__duration." + unit);
        return translated == null || translated.isEmpty() ? unit : translated;
    }
}
